import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.DHSXpJLs.js";const b=JSON.parse('{"title":"沙箱执行环境（aibim_sandbox）","description":"","frontmatter":{},"headers":[],"relativePath":"development/sandbox.md","filePath":"development/sandbox.md","lastUpdated":1790779354000}'),i={name:"development/sandbox.md"};function s(r,t,c,l,n,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="沙箱执行环境-aibim-sandbox" tabindex="-1">沙箱执行环境（aibim_sandbox） <a class="header-anchor" href="#沙箱执行环境-aibim-sandbox" aria-label="Permalink to &quot;沙箱执行环境（aibim_sandbox）&quot;">​</a></h1><p>两个 Python 编辑服务的 <code>script/run</code> 和 <code>script/save</code> 会在服务端执行用户或 AI 写的构建脚本。脚本执行就是代码执行，所以全部跑在沙箱里。</p><p>沙箱实现在共享包 <code>services/sandbox</code>（包名 <code>aibim_sandbox</code>），两个服务以 uv path editable 方式引用。它同时是 script-as-source 七个领域模块的唯一事实源：暂存、版本、diff、参数、编辑、定位、校验，两个服务共享同一份实现，各自只留薄适配。</p><h2 id="后端-生产只有-bwrap-一条路" tabindex="-1">后端：生产只有 bwrap 一条路 <a class="header-anchor" href="#后端-生产只有-bwrap-一条路" aria-label="Permalink to &quot;后端：生产只有 bwrap 一条路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后端</th><th>隔离能力</th><th>适用场景</th></tr></thead><tbody><tr><td><code>bwrap</code>（bubblewrap）</td><td>按需只读挂载，沙箱外写入直接 EROFS；断网</td><td>生产唯一路径</td></tr><tr><td><code>rlimit</code></td><td>rlimits 加独立工作目录，网络和外部文件系统不拦截</td><td>仅测试，须显式选择</td></tr></tbody></table><ul><li>没有 bwrap 时 run/save 拒绝执行，返回 503，不降级。</li><li>后端用 <code>SANDBOX_BACKEND</code> 选择，取值 <code>auto</code>、<code>bwrap</code>、<code>rlimit</code>，非法值启动即失败。<code>rlimit</code> 生产环境不要设。旧的 <code>ALLOW_RLIMIT_FALLBACK</code> 已删除，设了也不生效。</li><li>启动日志会打印后端探测结果，部署时确认看到 bwrap 可用。</li><li>安装：Debian/Ubuntu 用 <code>sudo apt install bubblewrap</code>，RHEL 系用 <code>sudo dnf install bubblewrap</code>，并确认 <code>user.max_user_namespaces</code> 大于 0。</li></ul><h2 id="资源与并发限额" tabindex="-1">资源与并发限额 <a class="header-anchor" href="#资源与并发限额" aria-label="Permalink to &quot;资源与并发限额&quot;">​</a></h2><table tabindex="0"><thead><tr><th>env</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>SCRIPT_RUN_CONCURRENCY</code></td><td><code>3</code></td><td>run/save 并发上限，满时返回 429</td></tr><tr><td><code>SCRIPT_MAX_FSIZE_BYTES</code></td><td><code>256 MiB</code></td><td>单文件写入上限</td></tr><tr><td><code>SCRIPT_MAX_OUTPUT_BYTES</code></td><td><code>1 MiB</code></td><td>stdout 加 stderr 累计上限</td></tr><tr><td><code>SCRIPT_MAX_PRODUCT_BYTES</code></td><td><code>256 MiB</code></td><td>产物与 map 发布上限</td></tr></tbody></table><p>两个服务同名同义。执行超时 60 秒，超时连孙进程一起终止。</p><h2 id="依赖环境-pep-723-加-uv-缓存" tabindex="-1">依赖环境：PEP 723 加 uv 缓存 <a class="header-anchor" href="#依赖环境-pep-723-加-uv-缓存" aria-label="Permalink to &quot;依赖环境：PEP 723 加 uv 缓存&quot;">​</a></h2><p>脚本可以在头部声明依赖：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /// script</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dependencies = [&quot;ifcopenshell&gt;=0.8&quot;, &quot;numpy&quot;]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> ///</span></span></code></pre></div><ul><li>声明即全量。写了 dependencies 就替换默认集；不写就注入服务默认集，ifc 侧是 <code>ifcopenshell&gt;=0.8</code> 加 <code>numpy</code>，cad 侧是 <code>ezdxf&gt;=1.3</code>。</li><li>依赖由宿主机进程解析：用 uv 建 venv、只装 wheel，按依赖集内容寻址缓存。沙箱内断网执行。</li><li>run/save 依赖 <code>uv</code> 二进制。缺 uv 返回 503，属于部署问题；依赖解析失败返回 422，属于脚本声明问题，报错带 uv 输出截尾。</li><li>缓存根 <code>SANDBOX_ENV_CACHE_DIR</code> 默认在 <code>$XDG_CACHE_HOME/aibim-sandbox-envs</code>。不要配到 data/ 或 /tmp 下面，前者 bwrap 不会挂载，后者是临时卷语义。</li><li>依赖构建超时用 <code>SCRIPT_ENV_BUILD_TIMEOUT_S</code> 控制，默认 300 秒。</li></ul><h2 id="失败语义速查" tabindex="-1">失败语义速查 <a class="header-anchor" href="#失败语义速查" aria-label="Permalink to &quot;失败语义速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态码</th><th>含义</th></tr></thead><tbody><tr><td>422</td><td>契约校验失败、沙箱构建失败或依赖解析失败。请求零副作用，按报错修正后重发</td></tr><tr><td>429</td><td>并发闸满，稍后重试</td></tr><tr><td>503</td><td>沙箱不可用，缺 bwrap 或缺 uv，属于部署问题</td></tr></tbody></table><p>编辑层还有一个 409（暂存脚本与 ScriptMap 分叉），不属于沙箱语义，定义在 <a href="/SourceAEC/reference/edit-api#定位链路">IFC 编辑 API</a>。现象级速查见<a href="/SourceAEC/guide/troubleshooting#状态码去哪查">故障排查</a>。</p>`,16)])])}const u=e(i,[["render",s]]);export{b as __pageData,u as default};
